#[derive(Debug, Clone, Copy)]
pub struct Tools<'a> {
    pub chat: &'a Chat,
    pub rules: &'a Rules,
    pub embedder: &'a Embedder,
    pub extractor: &'a Extractor,
    pub mode: Mode,
    pub cutoff: Option<f32>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Carry {
    pub list: SessionList,
    pub budget: Budget,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Decision {
    outcomes: Vec<Outcome>,
    answer: Option<Answer>,
    rulings: Vec<Ruling>,
    failures: Vec<String>,
    carry: Carry,
}

impl Decision {
    pub fn outcomes(&self) -> &[Outcome] {
        &self.outcomes
    }

    pub fn answer(&self) -> Option<&Answer> {
        self.answer.as_ref()
    }

    pub fn rulings(&self) -> &[Ruling] {
        &self.rulings
    }

    pub fn failures(&self) -> &[String] {
        &self.failures
    }

    pub fn into_carry(self) -> Carry {
        self.carry
    }
}

pub async fn decide(
    tools: &Tools<'_>,
    exchange_id: &str,
    checked: &[Checked],
    outcomes: Vec<Outcome>,
    carry: Carry,
    now: Timestamp,
) -> Decision {
    debug_assert!(
        crate::hist::validate::is_id(exchange_id),
        "decide: exchange_id is an exchange id"
    );
    debug_assert!(checked.len() == outcomes.len(), "decide: one outcome per checked rule");
    debug_assert!(
        tools.cutoff.is_none_or(super::twin::is_cutoff),
        "decide: the cutoff is above 0 and at most 1"
    );
    let judgeables = judgeables_of(&outcomes);
    let budget = carry.budget;
    let result: Decision = todo!("decide {now}");
    debug_assert!(
        result.outcomes.len() == checked.len(),
        "decide: one outcome per checked rule, none added"
    );
    debug_assert!(
        result.rulings.is_empty() || result.rulings.len() == judgeables.len(),
        "decide: one ruling per judgeable, or none"
    );
    debug_assert!(
        !result.rulings.is_empty() || judgeables.is_empty() || !result.failures.is_empty(),
        "decide: judgeables with no ruling carry a failure"
    );
    debug_assert!(
        tools.mode == Mode::Active || saves_nothing(&result, budget),
        "decide: shadow saves nothing and spends no budget"
    );
    debug_assert!(
        result.failures.iter().all(|f| !f.trim().is_empty()),
        "decide: no failure is blank"
    );
    result
}

pub fn judgeables_of(outcomes: &[Outcome]) -> Vec<usize> {
    let result: Vec<usize> = todo!("judgeables_of {outcomes:?}");
    debug_assert!(
        result.iter().all(|&at| outcomes[at].is_open() && outcomes[at].is_judged()),
        "judgeables_of: only an open and judged outcome goes to novelty"
    );
    debug_assert!(
        result.windows(2).all(|w| w[0] < w[1]),
        "judgeables_of: in outcome order, once each"
    );
    result
}

pub async fn neighbours_of(
    rules: &Rules,
    candidate: &RuleCandidate,
    top_k: u32,
) -> Result<Vec<Known>, String> {
    debug_assert!(top_k > 0, "neighbours_of: top_k is above 0");
    let result: Result<Vec<Known>, String> = todo!("neighbours_of {rules:?} {candidate:?}");
    debug_assert!(
        result.as_ref().map_or(true, |n| n.len() <= top_k as usize),
        "neighbours_of: at most top_k neighbours"
    );
    result
}

pub fn neighbour_of(rule: &Rule) -> Known {
    debug_assert!(!rule.body.if_.trim().is_empty(), "neighbour_of: the rule has an if");
    debug_assert!(!rule.body.do_.is_empty(), "neighbour_of: the rule has a do");
    let result: Known = todo!("neighbour_of");
    result
}

pub fn known_for(neighbours: Vec<Known>, list: &SessionList) -> Vec<Known> {
    let count = neighbours.len() + list.items().len();
    let result: Vec<Known> = todo!("known_for");
    debug_assert!(result.len() <= count, "known_for: nothing is invented");
    debug_assert!(
        result.ends_with(list.items()),
        "known_for: the session items come last, in order"
    );
    debug_assert!(
        unique_keys(&result),
        "known_for: no neighbour twice"
    );
    result
}

fn unique_keys(known: &[Known]) -> bool {
    todo!("unique_keys {known:?}")
}

fn saves_nothing(decision: &Decision, before: Budget) -> bool {
